char buf[sizeof(uint64_t)];
    std::memcpy(buf, &value, sizeof(uint64_t));
    dst->append(buf, sizeof(buf));
    // Ensure little-endian encoding (LevelDB's requirement)
    if (std::endian::native == std::endian::big) {
        for (size_t i = 0; i < sizeof(uint64_t) / 2; ++i) {
            std::swap(buf[i], buf[sizeof(uint64_t) - 1 - i]);
        }
    }
